codeExample.code:
-- 假设 users 表有 (id, name, age, city)，二级索引 idx_name_age(name, age)

-- 需要回表：SELECT * 需要完整行数据，索引只有 name, age
EXPLAIN SELECT * FROM users WHERE name = '张三';
-- Extra: NULL（需要回表取完整行）

-- 不需要回表（覆盖索引）：只查索引中包含的列
EXPLAIN SELECT name, age FROM users WHERE name = '张三';
-- Extra: Using index（覆盖索引，无需回表）

-- 不需要回表：主键也在二级索引的叶子节点中
EXPLAIN SELECT id, name, age FROM users WHERE name = '张三';
-- Extra: Using index（id 是主键，二级索引叶子节点自带）

-- 索引列 phone VARCHAR(20)

-- ❌ 隐式类型转换导致索引失效
SELECT * FROM users WHERE phone = 13800138000;
-- 等价于 WHERE CAST(phone AS signed) = 13800138000

-- ✅ 正确写法
SELECT * FROM users WHERE phone = '13800138000';

-- ❌ 函数导致索引失效
SELECT * FROM orders WHERE DATE(create_time) = '2024-01-01';

-- ✅ 改写为范围查询
SELECT * FROM orders WHERE create_time >= '2024-01-01'
  AND create_time < '2024-01-02';
